{"command":"python3 << 'EOF'
import csv

# Read trips.txt
with open('inputs/gtfs/sample_city_gtfs.zip', 'r', encoding='latin-1') as f:
    reader = csv.reader(f)
    trips_data = []
    for row in reader:
        if len(row) >= 3:
            route_id = row[2]
            service_id = row[1]
            trip_id = row[3]
            trips_data.append((route_id, service_id, trip_id))

# Read clean stop_times
with open('outputs/t05_clean_stop_times.csv', 'r', encoding='latin-1') as f:
    reader = csv.DictReader(f)
    stop_times = []
    for row in reader:
        stop_times.append(row)

# Build a map from trip_id to route_id
trip_to_route = {}
for route_id, service_id, trip_id in trips_data:
    trip_to_route[trip_id] = route_id

print("Sample trip_id to route_id mapping:")
for i in range(min(10, len(trip_to_route))):
    print(f"  {trip_to_route.get(i)[:20]}")

print("\nChecking stop 5015050104:")
for rt in stop_times:
    if rt['stop_id'] == '5015050104':
        print(f"  trip_id: {rt['trip_id']}, route_id: {trip_to_route.get(rt['trip_id'])}, departure_time: {rt['departure_time']}")
EOF"}

