        if 'trips' in name.lower():
            content = zf.read(name).decode('latin-1')
            reader = csv.reader(content)
            for row in reader:
                if len(row) >= 3:
                    route_id = row[2]
                    service_id = row[1]
                    trip_id = row[3]
                    print(f"route_id: {route_id}, service_id: {service_id}, trip_id: {trip_id}")
EOF"}

